type Mode = "list" | "detail" | "edit" | "create" | "confirm-delete";

function ProductsScreen() {
  const { data: products = [] } = useQuery({ queryKey: ["products", "list"], queryFn: api.listProducts });
  const [screen, dispatch] = useReducer(reduce, initialScreen);
  const selected = products.find((p) => p.id === screen.selectedId) ?? null; // derived, never copied

  return (
    <div className="grid grid-cols-2 gap-4">
      <ProductList products={products} onSelect={(id) => dispatch({ type: "select", id })} />
      {screen.mode === "detail" && selected && (
        <ProductDetail product={selected} onEdit={() => dispatch({ type: "edit" })}
          onDelete={() => dispatch({ type: "delete" })} />
      )}
      {(screen.mode === "edit" || screen.mode === "create") && (
        <ProductForm key={screen.selectedId ?? "new"} draft={screen.draft}
          onChange={(title) => dispatch({ type: "change", title })}
          onSave={() => dispatch({ type: "save" })} onCancel={() => dispatch({ type: "cancel" })} />
      )}
      {screen.mode === "confirm-delete" && selected && (
        <ConfirmDialog title={`Delete ${selected.name}?`}
          onConfirm={() => dispatch({ type: "confirm" })} onCancel={() => dispatch({ type: "cancel" })} />
      )}
    </div>
  );
}
